WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "title" = $1 , "score" = "s"."score" + $2 FROM "public"."mutation_item" AS "b0" WHERE "s"."id" = "b0"."id" AND ( ( true ) ) RETURNING "s" AS "t0" , "b0"."ctid" AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) , 'returning' , (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" , "t0"."score" AS "score" , "t0"."note" AS "note" , "c4"."j" AS "owner" ) AS "%")) ), '[]') FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."name" AS "name" , "c1"."j" AS "items_aggregate" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."mutation_author" AS "s" WHERE true AND "s"."id" = "t0"."owner_id" AND ( ( true ) ) LIMIT 1 ) AS "t1" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT row_to_json((SELECT "%" FROM (SELECT count( "t2" .*) AS "count" , row_to_json((SELECT "%" FROM (SELECT sum( "t2"."score" ) AS "score" ) AS "%")) AS "sum" ) AS "%")) AS "aggregate" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "w0" AS "s" WHERE true AND "s"."owner_id" = "t1"."id" AND ( ( true ) ) ) AS "t2" ) AS "c1" ON true ) AS "c4" ON true ) )
